<?php
declare(strict_types=1);require_once __DIR__.'/includes/layout.php';require_once __DIR__.'/includes/service_engine.php';login_required();$pdo=db();
if($_SERVER['REQUEST_METHOD']==='POST'){verify_csrf();$action=post('action');$id=post('id');if($action==='delete'&&$id!==''){try{$pdo->prepare("DELETE FROM `restaurant` WHERE `restaurant_name`=?")->execute([$id]);flash('success','Restaurant deleted.');}catch(Throwable $e){flash('error','This record is in use and cannot be deleted.');}}redirect('restaurant.php');}
$rows=$pdo->query('SELECT * FROM `restaurant` ORDER BY `restaurant_name` DESC')->fetchAll();page_header('Restaurant','restaurant');?>
<div class="page-head"><div><h1>Restaurant</h1><p class="muted">Manage Restaurant records and related guest services.</p></div><a class="btn primary" href="restaurant_form.php">Add Restaurant</a></div>
<section class="card table-wrap"><table><thead><tr><th>ID</th><th>Open</th><th>Close</th><th>Details</th><th>Actions</th></tr></thead><tbody>
<?php foreach($rows as $r):?><tr><td><?=e($r['restaurant_name'])?></td><td><?=e($r['restaurant_open_time'])?></td><td><?=e($r['restaurant_close_time'])?></td><td><?=e($r['restaurant_details'])?></td><td class="actions"><a href="restaurant_form.php?id=<?=urlencode((string)$r['restaurant_name'])?>">Edit</a><a href="restaurant_service.php?id=<?=urlencode((string)$r['restaurant_name'])?>">Add Service</a><form method="post" onsubmit="return confirm('Are you sure?')"><?=csrf_field()?><input type="hidden" name="action" value="delete"><input type="hidden" name="id" value="<?=e($r['restaurant_name'])?>"><button class="danger-link">Delete</button></form></td></tr><?php endforeach;?><?php if(!$rows):?><tr><td colspan="5" class="empty">No records.</td></tr><?php endif;?></tbody></table></section><?php page_footer();?>
